import React from "react";
import { Treemap, ResponsiveContainer } from "recharts";

const data = [
  { name: "Äpplen", value: 100, img: "./components/Thumbs/Urusei Yatsura thumb.png" },
  { name: "Bananer", value: 80, img: "https://m.media-amazon.com/images/S/pv-target-images/1addbce171260179bd4529ad15a2c3ac26b9f9783a70eb66627546c7f31b7708.jpg" },
  { name: "Körsbär", value: 60, img: "./components/Thumbs/ganmo.jpg" },
  { name: "Druvor", value: 40, img: "./components/Thumbs/Dirty Pair.jpg" },
];

const CustomizedContent = (props) => {
  const { x, y, width, height, name, img } = props;
  return (
    <g>
      <rect
        x={x}
        y={y}
        width={width}
        height={height}
        style={{ fill: "none", stroke: "#fff" }}
      />
      <image
        href={img}
        x={x + 5}
        y={y + 5}
        width={width - 10}
        height={height - 30}
        preserveAspectRatio="xMidYMid slice"
      />
      <text
        x={x + width / 2}
        y={y + height - 10}
        textAnchor="middle"
        fontSize={12}
        fill="#333"
      >
        {name}
      </text>
    </g>
  );
};

export default function BildTreemap() {
  return (
    <ResponsiveContainer width="100%" height={400}>
      <Treemap
        data={data}
        dataKey="value"
        stroke="#fff"
        content={<CustomizedContent />}
      />
    </ResponsiveContainer>
  );
}
